import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Scanner;

public class Spielwiese {

    enum Zug { SCHERE, STEIN, PAPIER }

    public static String vergleiche(Zug spieler, Zug computer) {
        if (spieler == computer) {
            return "Unentschieden";
        }
        boolean gewonnen = (spieler == Zug.SCHERE && computer == Zug.PAPIER)
                || (spieler == Zug.STEIN && computer == Zug.SCHERE)
                || (spieler == Zug.PAPIER && computer == Zug.STEIN);
        return gewonnen ? "Gewonnen!" : "Verloren!";
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Zug[] computerZuege = {Zug.STEIN, Zug.SCHERE};
        int siege = 0;

        for (int runde = 0; runde < computerZuege.length; runde++) {
            System.out.println("Runde " + (runde + 1) + ": computer=" + computerZuege[runde]);
            System.out.println("Dein Zug:");
            Zug spieler = Zug.valueOf(scanner.nextLine());
            String ergebnis = vergleiche(spieler, computerZuege[runde]);
            System.out.println(ergebnis);
            if (ergebnis.equals("Gewonnen!")) {
                siege++;
            }
        }

        Path datei = Path.of("highscore.txt");
        try {
            Files.writeString(datei, "Siege: " + siege);
            System.out.println("Highscore-Datei: " + Files.readString(datei));
        } catch (IOException e) {
            System.out.println("Datei-Problem: " + e.getMessage());
        }
    }
}
